/**
 * Buy-page supply matcher: parity with the scheduler's Python matcher (cloud_hunter/saas/matching.py) and the
 * GET /supply route (count, sample, broaden suggestions).
 * fixtures/supply-match-cases.json is generated by calling the real Python functions (title_ok, location_ok,
 * evaluate, expand_titles); regenerate it when the Python rules change.
 * Run: npm run test:autoapply
 */
import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import express from "express";

import {
  evaluate, expandTitles, locationOk, titleOk, userCtx, titleKeywords, titleMatch, broadenOptions, relatedTitles,
} from "../lib/autoapply/supplyMatch.js";
import { createAutoApplyRouter } from "../routes/autoapply.js";
import { createFakeDb } from "./fixtures/fakeSupabase.mjs";

const cases = JSON.parse(fs.readFileSync(new URL("./fixtures/supply-match-cases.json", import.meta.url), "utf8"));
const ctx = (titles, locations = [], extra = {}) => ({ ...userCtx({ prefs: { titles, locations } }), ...extra });

test("title_ok parity with Python", () => {
  const bad = cases.title.filter((c) => titleOk(c.title, ctx(c.wanted)) !== c.ok);
  assert.deepEqual(bad, []);
  assert.ok(cases.title.length >= 30);
});

test("location_ok parity with Python", () => {
  const bad = cases.location.filter((c) => locationOk(c.location, null, c.wanted) !== c.ok);
  assert.deepEqual(bad, []);
});

test("evaluate parity with Python (blocked, current employer, seniority)", () => {
  const bad = cases.evaluate.filter((c) => {
    const u = ctx(c.user.titles, c.user.locations, { years: c.user.years, blocked: c.user.blocked, currentEmployer: c.user.emp });
    const r = evaluate(c.job, u);
    return r.ok !== c.ok || r.reason !== c.reason;
  });
  assert.deepEqual(bad, []);
});

test("expand_titles parity with Python", () => {
  for (const [t, want] of Object.entries(cases.expand)) assert.deepEqual(expandTitles([t]), want, t);
});

test("prefilter keywords never drop a title the matcher accepts", () => {
  const sets = [...new Set(cases.title.map((c) => JSON.stringify(c.wanted)))].map((s) => JSON.parse(s)).filter((w) => w.length);
  for (const wanted of sets) {
    const kws = titleKeywords(expandTitles(wanted));
    if (!kws) continue;
    for (const c of cases.title.filter((x) => JSON.stringify(x.wanted) === JSON.stringify(wanted) && x.ok)) {
      assert.ok(kws.some((k) => c.title.toLowerCase().includes(k)), `${c.title} dropped by ${kws} for ${wanted}`);
    }
  }
  assert.ok(titleKeywords(["Software Engineer"]).includes("swe"));
  assert.ok(titleMatch("SWE III", "Software Engineer"));
});

test("userCtx: years from answers / experience, current employer from the open experience entry", () => {
  const row = { profile: { experience: [{ company: "Acme", start: "2020-01", end: "2022-01" }, { company: "Beta", start: "2022-01" }] }, prefs: {} };
  const u = userCtx(row, {});
  assert.equal(u.currentEmployer, "Beta");
  assert.ok(u.years > 4);
  assert.equal(userCtx(row, { "facts.total_experience_years": "3" }).years, 3);
});

test("broaden options: only real changes", () => {
  const ids = (p) => broadenOptions(p).map((o) => o.id);
  assert.deepEqual(ids({ titles: ["Software Engineer"], locations: ["Pune"] }), ["india", "remote", "metros", "related"]);
  assert.deepEqual(ids({ titles: [], locations: [] }), []);
  assert.deepEqual(ids({ titles: [], locations: ["Pune", "Remote"] }), ["india", "metros"]);
  const metros = broadenOptions({ locations: ["Bengaluru", "Mumbai"] }).find((o) => o.id === "metros");
  assert.deepEqual(metros.added, ["Hyderabad", "Delhi", "Gurugram", "Noida", "Chennai"]);
  assert.equal(metros.label, "Add nearby metros (Hyderabad, Delhi NCR, Chennai)");
  assert.deepEqual(relatedTitles(["Software Engineer"]), ["Data Engineer", "DevOps Engineer", "Cloud Engineer", "QA Engineer"]);
  assert.deepEqual(relatedTitles(["A", "B", "C", "D", "Software Engineer"]), []);
  assert.ok(!relatedTitles(["Software Engineer"]).includes("Software Engineer"));
});

// ── route ────────────────────────────────────────────────────────────────────
const U = "bbbbbbbb-0000-4000-8000-000000000001";
const NOPREF = "bbbbbbbb-0000-4000-8000-000000000002";
const day = (n) => new Date(Date.now() - n * 86400000).toISOString();
let i = 0;
const job = (title, location, extra = {}) => ({
  job_key: `gh:x:${++i}`, ats: "greenhouse", company: `Co${i}`, company_key: `co${i}`, company_kind: "product",
  title, location, country: "IN", posted_at: day(1), closed_at: null, description: null, ...extra,
});
const rows = [
  job("Software Engineer II", "Pune, Maharashtra"),
  job("SDE-2", "Pune"),
  job("Backend Developer", "Pune", { ats: "lever" }),
  job("Senior Software Engineer", "Bengaluru, Karnataka"),
  job("Software Engineer", "Hyderabad"),
  job("Software Developer", "Remote - India"),
  job("Software Engineer", "Gurugram"),
  job("Data Engineer", "Pune"),
  job("Software Engineering Intern", "Pune"),
  job("Account Executive", "Pune"),
  job("Software Engineer", "Pune", { company: "Blocked Inc", company_key: "blocked" }),
  job("Software Engineer", "Pune", { posted_at: day(10) }),
  job("Software Engineer", "Pune", { closed_at: day(0) }),
  job("Software Engineer", "Pune", { company_kind: "service" }),
];
const db = createFakeDb({
  aa_profiles: [
    { user_id: U, consent_at: day(1), onboarding_done: true, prefs: { titles: ["Software Engineer"], locations: ["Pune"], blocked_companies: ["Blocked Inc"] }, profile: {} },
    { user_id: NOPREF, consent_at: day(1), onboarding_done: true, prefs: {}, profile: {} },
  ],
  aa_jobs: rows,
});
let server;
let base;
before(async () => {
  const app = express();
  app.use(express.json());
  app.use("/api/autoapply", createAutoApplyRouter({
    db,
    getUserPlan: async () => "pro",
    authenticate: (req, _res, next) => { req.user = { id: String(req.headers.authorization || "").replace("Bearer ", ""), email: "x@example.com" }; next(); },
    razorpay: { isEnabled: () => false },
  }));
  server = app.listen(0);
  await new Promise((r) => server.once("listening", r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server && server.close());
const get = async (uid, q) => {
  const r = await fetch(`${base}/api/autoapply/supply?${q}`, { headers: { Authorization: `Bearer ${uid}` } });
  return { status: r.status, json: await r.json() };
};

test("GET /supply: scheduler gates, by_ats, sample, broaden counts", async () => {
  const r = await get(U, "kind=product&window_days=3");
  assert.equal(r.status, 200);
  // SWE II, SDE-2, Backend Developer in Pune; not the data engineer, intern, sales, blocked, old, closed or service job
  assert.equal(r.json.count, 3);
  assert.deepEqual(r.json.by_ats, { greenhouse: 2, lever: 1 });
  assert.ok(r.json.sample.length <= 8);
  assert.deepEqual(Object.keys(r.json.sample[0]).sort(), ["company", "location", "posted_at", "title"]);
  const by = Object.fromEntries(r.json.broaden.map((b) => [b.id, b]));
  assert.equal(by.india.count, 7); // every location
  assert.deepEqual(by.india.locations, ["Pune", "Pan India"]);
  assert.equal(by.remote.count, 4);
  assert.equal(by.metros.count, 6); // + Bengaluru, Hyderabad, Gurugram (as part of Delhi NCR)
  assert.equal(by.related.count, 4); // + Data Engineer
  assert.ok(r.json.broaden.every((b) => b.count > r.json.count));
});

test("GET /supply: no prefs falls back to the default engineering titles, nothing to broaden", async () => {
  const r = await get(NOPREF, "kind=product&window_days=3");
  assert.equal(r.status, 200);
  assert.equal(r.json.count, 9); // every engineering title (titles.INCLUDE) but the intern and the sales seat
  assert.deepEqual(r.json.broaden, []);
});
